/**
 * The monthly usage statement as plain text, for a fixed-width font.
 * All arithmetic is in whole cents; amounts are shown as dollars and cents.
 * @param {{ customer: string, account: string, period: string, currency: string,
 *           lines: { service: string, quantity: number, unit: string, amount_cents: number }[],
 *           credits: { reason: string, amount_cents: number }[] }} data
 * @returns {string}
 */

const MAX_WIDTH = 72;
const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

/** "2026-09" -> "September 2026" (unrecognised periods are shown as given). */
function monthName(period) {
  const m = /^(\d{4})-(\d{2})$/.exec(period);
  if (!m || Number(m[2]) < 1 || Number(m[2]) > 12) return period;
  return `${MONTHS[Number(m[2]) - 1]} ${m[1]}`;
}

/** Whole number with thousands separators: 18250 -> "18,250". */
function count(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

/** Cents as dollars and cents: 164250 -> "1,642.50", -16425 -> "-164.25". */
function money(cents) {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  return `${sign}${count(Math.floor(abs / 100))}.${String(abs % 100).padStart(2, "0")}`;
}

export function renderStatement(data) {
  const charges = data.lines.map((l) => ({
    label: l.service,
    qty: count(l.quantity),
    unit: l.unit,
    amount: money(l.amount_cents),
  }));
  const credits = data.credits.map((c) => ({ label: c.reason, amount: money(c.amount_cents) }));
  const chargeCents = data.lines.reduce((sum, l) => sum + l.amount_cents, 0);
  const creditCents = data.credits.reduce((sum, c) => sum + c.amount_cents, 0);
  const total = money(chargeCents + creditCents);

  const amountHead = `Amount (${data.currency})`;
  const labelW = Math.max(...charges.map((r) => r.label.length), ...credits.map((r) => r.label.length), "Total due".length);
  const qtyW = Math.max(...charges.map((r) => r.qty.length), "Quantity".length);
  const unitW = Math.max(...charges.map((r) => r.unit.length), "Unit".length);
  const amountW = Math.max(
    amountHead.length,
    total.length,
    ...charges.map((r) => r.amount.length),
    ...credits.map((r) => r.amount.length),
  );
  const width = labelW + 2 + qtyW + 2 + unitW + 2 + amountW;
  if (width > MAX_WIDTH) throw new Error(`statement would be ${width} characters wide; the limit is ${MAX_WIDTH}`);

  const left = (s, w) => s.padEnd(w);
  const right = (s, w) => s.padStart(w);
  const rule = "-".repeat(width);
  // Credits and the total have no quantity or unit, so the amount sits in the same column.
  const gap = labelW + 2 + qtyW + 2 + unitW + 2;
  const amountOnly = (label, amount) => `${left(label, labelW)}${" ".repeat(gap - labelW)}${right(amount, amountW)}`;

  const out = [];
  out.push(data.customer);
  out.push(`Usage statement for ${monthName(data.period)}`);
  out.push(`Account ${data.account}`);
  out.push("");
  out.push(`${left("Charges", labelW)}  ${right("Quantity", qtyW)}  ${left("Unit", unitW)}  ${right(amountHead, amountW)}`);
  out.push(rule);
  for (const r of charges) {
    out.push(`${left(r.label, labelW)}  ${right(r.qty, qtyW)}  ${left(r.unit, unitW)}  ${right(r.amount, amountW)}`);
  }
  out.push("");
  out.push("Credits");
  out.push(rule);
  for (const r of credits) out.push(amountOnly(r.label, r.amount));
  out.push("");
  out.push(rule);
  out.push(amountOnly("Total due", total));
  return `${out.join("\n")}\n`;
}
EOF
